import { AudioMixer } from './mixer.js'; import { MusicDirector } from './music.js'; import { NullAudioBackend } from './backends/null-backend.js';
export class AudioSystem { constructor(backend = new NullAudioBackend()) { this.backend = backend; this.mixer = new AudioMixer(backend); this.music = new MusicDirector(this); this.ready = false; } async init() { try { this.ready = await this.backend.init() !== false; } catch { this.backend = new NullAudioBackend(); await this.backend.init(); this.mixer = new AudioMixer(this.backend); this.ready = true; } return this.ready; } play(cue, options = {}) { try { return this.backend.play(cue, options); } catch { return null; } } setMusic(state) { return this.music.set(state); } setVolume(bus, volume) { this.mixer.set(bus, volume); } async dispose() { await this.backend.dispose?.(); } }
